(N, M) = map(int, input().split(' '))
arr = list(map(int, input().split(' ')))
query = []
for _ in range(M):
	query.append(list(input().split()))
pointer = 0
for each in query:
	if each[0] == 'C':
		pointer += int(each[1])
	elif each[0] == 'A':
		pointer -= int(each[1])
	else:
		print(arr[(pointer + int(each[1]) - 1) % N])
